BASE='/mnt/lima-afsbdata/afs-delivery/repair-v55-b'
ROLES=['node']

import hashlib,json,os,pathlib,subprocess
base=pathlib.Path(BASE)
result={'processes':{},'config_sha256':{}}
for role in ROLES:
 p=int((base/'run'/(role+'.pid')).read_text()); proc=pathlib.Path('/proc')/str(p)
 result['processes'][role]={'pid':p,'ticks':(proc/'stat').read_text().rsplit(') ',1)[1].split()[19],'exe':os.readlink(proc/'exe'),'sha256':hashlib.sha256((proc/'exe').read_bytes()).hexdigest()}
 result['config_sha256'][role]=hashlib.sha256((base/'etc'/(role+'.toml')).read_bytes()).hexdigest()
print(json.dumps(result))
